// Drizzle schema. `npm run db:generate -w @windle/api` diffs this file against ./drizzle and writes the next SQL
// migration; `node dist/migrate.js` applies them (explicit deploy step, never at api startup).
import { sql } from 'drizzle-orm';
import { bigint, check, index, inet, pgTable, primaryKey, text, timestamp, uuid } from 'drizzle-orm/pg-core';

const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

/**
 * Users. `id` is a UUIDv7 generated by the api (Postgres 17 has no uuidv7()): time-ordered, so inserts append to the
 * B-tree like a bigint would, but ids are not enumerable and do not leak signup counts, and the public contract
 * (`Me.id`) is a uuid.
 */
export const users = pgTable('users', {
  id: uuid('id').primaryKey(),
  createdAt: timestamptz('created_at').notNull().defaultNow(),
});

/** Wallets proven by a SIWS signature. One wallet belongs to exactly one user; a user may link several later. */
export const wallets = pgTable(
  'wallets',
  {
    chain: text('chain').notNull().default('solana'),
    address: text('address').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    firstSeen: timestamptz('first_seen').notNull().defaultNow(),
    lastSeen: timestamptz('last_seen').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: 'wallets_pkey', columns: [t.chain, t.address] }),
    index('wallets_user_id_idx').on(t.userId),
    check('wallets_chain_check', sql`${t.chain} in ('solana')`),
    check('wallets_address_check', sql`char_length(${t.address}) between 32 and 44`),
  ],
);

/**
 * Append-mostly audit trail of sessions. The live session is in Redis; this table answers "who signed in, when,
 * from where, and when did it end". `session_hash` is sha256(token) hex, the same value Redis keys on: the raw
 * token is never stored anywhere, so a leaked row cannot be replayed as a cookie.
 */
export const sessionsAudit = pgTable(
  'sessions_audit',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    sessionHash: text('session_hash').notNull().unique('sessions_audit_session_hash_key'),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    method: text('method').notNull(),
    walletAddress: text('wallet_address'),
    ip: inet('ip'),
    userAgent: text('user_agent'),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
    expiresAt: timestamptz('expires_at').notNull(),
    revokedAt: timestamptz('revoked_at'),
    revokeReason: text('revoke_reason'),
  },
  (t) => [
    index('sessions_audit_user_id_created_at_idx').on(t.userId, t.createdAt),
    check('sessions_audit_method_check', sql`${t.method} in ('siws', 'email', 'x', 'google')`),
    check('sessions_audit_session_hash_check', sql`${t.sessionHash} ~ '^[0-9a-f]{64}$'`),
    check('sessions_audit_user_agent_check', sql`char_length(${t.userAgent}) <= 512`),
  ],
);
